q=root/'.atena/generated/CHATGPT-FILA-022-vfx-projeteis-e-explosoes.md';t=read(q);old='- [x] gerada · [ ] aprovada · candidata: `'+g['candidate']+'` — gate humano pendente; fonte nativa preservada.';assert old in t
