 s=s.replace('S-007 FILA021 gerada: E/F seis candidatas cada revisadas; P01 v01 gerada, gate humano pendente.','S-007 P01 aprovada pelo dono; gerando sete P, depois somente gate Q01. Manifesto202 preservado.')
 s=s.replace('Aguardar aprovacao P01 antes dos sete demais P; 95 fontes VFX restantes. Retorno PLAN-071 preservado.','Revisar ciclo de voo e quatro impactos P; gerar Q01 para proximo gate humano. Retorno PLAN-071 preservado.')
 s=s.replace('S-007 E/F completos como candidatas; aguardando gate humano P01. PLAN-071 preservado.','S-007 P em geracao apos aceite P01; proximo gate Q01. PLAN-071 preservado.')
 if rel.endswith('plan-053-imagens.yaml'):
  s=s.replace('  id: GATE-FILA-022-P01-2026-10-09\n  status: PENDING_OWNER_APPROVAL','  id: GATE-FILA-022-P01-2026-10-09\n  status: APPROVED')
  s=s.replace('  receipt: .atena/generated/s007-reconciliation/v01/p01-owner-gate-2026-10-09.json\n','  receipt: .atena/generated/s007-reconciliation/v01/p01-owner-gate-2026-10-09.json\n  owner_reply: "atena, aprovado, continue"\n  approval_receipt: .atena/generated/s007-reconciliation/v01/p01-owner-approval-2026-10-09.json\n')
  m=re.search(r'\nvfx_generation_progress:\n(.*?)(?=\n\S|\Z)',s,re.S);assert m;s=s[:m.start(1)]+'  jobs: .atena/generated/s007-reconciliation/v01/pq-generation-jobs-2026-10-09.json\n  native_generated_since_P01: 0\n  last_frame: none\n'+s[m.end(1):]
 p.write_text(s,encoding='utf-8')
